	if int32((*TunixFile)(unsafe.Pointer(pFile)).FctrlFlags)&(libc.Int32FromInt32(m_UNIXFILE_EXCL)|libc.Int32FromInt32(m_UNIXFILE_RDONLY)) == int32(m_UNIXFILE_EXCL) {
		if int32((*TunixInodeInfo)(unsafe.Pointer(pInode)).FbProcessLock) == 0 {
			(*(*Tflock)(unsafe.Pointer(bp))).Fl_whence = m_SEEK_SET
			(*(*Tflock)(unsafe.Pointer(bp))).Fl_start = int64(_sqlite3PendingByte + libc.Int32FromInt32(2))
			(*(*Tflock)(unsafe.Pointer(bp))).Fl_len = int64(m_SHARED_SIZE)
			(*(*Tflock)(unsafe.Pointer(bp))).Fl_type = int16(m_F_WRLCK)
			rc = (*(*func(*libc.TLS, int32, int32, uintptr) int32)(unsafe.Pointer(&struct{ uintptr }{_aSyscall[int32(7)].FpCurrent})))(tls, (*TunixFile)(unsafe.Pointer(pFile)).Fh, int32(m_F_SETLK), libc.VaList(bp+40, bp))
			if rc < 0 {
				return rc
			}
			(*TunixInodeInfo)(unsafe.Pointer(pInode)).FbProcessLock = uint8(1)
			(*TunixInodeInfo)(unsafe.Pointer(pInode)).FnLock++
		} else {
			rc = 0
		}
	} else {
		rc = (*(*func(*libc.TLS, int32, int32, uintptr) int32)(unsafe.Pointer(&struct{ uintptr }{_aSyscall[int32(7)].FpCurrent})))(tls, (*TunixFile)(unsafe.Pointer(pFile)).Fh, int32(m_F_SETLK), libc.VaList(bp+40, pLock))
	}
	return rc
